      : [el('span', { className: 'muted', textContent: 'none' })]),
  );
}

async function openPage(slug) {
  state.slug = slug;
  let view = null;
  try {
    view = await api(`/api/pages/${encodeURIComponent(slug)}`);
  } catch (err) {
    if (err.status !== 404) throw err;
