  if (!from || !to) return;
  const d = await api(`/api/pages/${encodeURIComponent(state.slug)}/diff?from=${from}&to=${to}`);
  const pre = $('#diff');
  pre.replaceChildren(
    ...d.lines.map((l) => {
      const line = el('span', { className: `diff-${l.op === ' ' ? 'same' : l.op === '+' ? 'add' : 'del'}`, textContent: `${l.op} ${l.text}\n` });
